comp.body:
query MyQuery($regionRuleId: uuid!) {
  AllowanceRegionRule(where: {id: {_eq: $regionRuleId}, isDeleted: {_eq: false}}) {
    id
    name
    code
    activeFrom
    activeTo
    version
    allowanceRegionRuleDetail(where: {isDeleted: {_eq: false}}) {
      id
      countryRef
      travelRegionRef
      amount
      currencyRef
      home
      activeFrom
      activeTo
    }
  }
}

